def validate_species_numbers():
    missing = [entry["species_id"] for entry in species_map_arr if not entry["species_number"]]
    if missing:
        raise ValueError(f"Species without spreadsheet numbers: {missing}")
    numbers = [entry["species_number"] for entry in species_map_arr]
    duplicates = sorted({number for number in numbers if numbers.count(number) > 1})
    if duplicates:
        raise ValueError(f"Duplicate spreadsheet species numbers: {duplicates}")
    print("All", len(species_map_arr), "species have unique spreadsheet numbers.")

def get_species_index_from_map_array(speciesName):
    return next((i for i, entry in enumerate(species_map_arr) if entry["species_id"] == speciesName), None)

if __name__ == "__main__":
    validate_species_numbers()

