class TeachableCategories:
    _instance = None  # For singleton instance

    def __new__(cls, *args, **kwargs):
        if cls._instance is None:
            cls._instance = super().__new__(cls)
        return cls._instance

    def __init__(self):
        
        self.tutor_str = "Move Tutor"
        self.tms_str = "TMs/HMs"
        self.setup_tutor_str = "Setup Tutor"
        self.tech_tutor_str = "Tech Tutor"
        self.display_order = [
            self.tms_str,
            self.tutor_str,
            self.tech_tutor_str,
            self.setup_tutor_str
        ]

    def get_display_order(self):
        """Get the display order of categories."""
        return self.display_order

    def get_category_label(self, key):
        """Get the label for a specific category key."""
        return getattr(self, key, None)


teachable_categories = TeachableCategories()
